use serde_json::Value;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Kind {
    Flag,
    Choice,
    Size,
    Color,
    Text,
}

#[derive(Clone, Copy, Debug)]
pub struct Spec {
    pub group: &'static str,
    pub key: &'static str,
    pub label: &'static str,
    pub kind: Kind,
    pub min: f64,
    pub max: f64,
    pub options: &'static [&'static str],
}

#[derive(Clone, Copy, Debug)]
pub struct ColorSpec {
    pub key: &'static str,
    pub label: &'static str,
    pub initial: [f64; 4],
}
#[derive(Clone, Copy, Debug)]
pub struct SizeSpec {
    pub key: &'static str,
    pub label: &'static str,
    pub initial: f64,
    pub min: f64,
    pub max: f64,
}
#[derive(Clone, Copy, Debug)]
pub struct Group {
    pub key: &'static str,
    pub section: &'static str,
    pub label: &'static str,
}

